:root {
  color-scheme: dark;
  font-family: system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
  font-size: 16px;
  background: #172b3a;
  color: #f7f3e8;
  --navy: #172b3a;
  --panel: #203b4b;
  --green: #8ecf76;
  --gold: #ffd166;
  --cream: #f7f3e8;
}

* { box-sizing: border-box; }
body {
  min-width: 360px;
  min-height: 100vh;
  margin: 0;
  display: grid;
  place-items: center;
  padding: 24px 16px;
  background: radial-gradient(ellipse at 50% 0%, #31556a 0, var(--navy) 68%);
}
.game-card {
  width: min(100%, 460px);
  padding: 32px clamp(20px, 7vw, 40px) 26px;
  text-align: center;
  border: 1px solid #527080;
  border-radius: 24px;
  background: var(--panel);
  box-shadow: 0 24px 60px #0b1824aa, inset 0 1px #ffffff12;
}
.eyebrow { margin: 0 0 8px; color: var(--gold); font-size: .8rem; font-weight: 800; letter-spacing: .16em; }
h1 { margin: 0; font-size: clamp(2rem, 9vw, 2.75rem); line-height: 1.1; letter-spacing: -.04em; }
.intro { margin: 10px 0 24px; color: #c4d2d8; }
.scoreboard { display: flex; justify-content: center; gap: 16px; margin-bottom: 20px; }
.stat { min-width: 112px; padding: 10px 16px; border: 1px solid #527080; border-radius: 14px; background: #172b3a; }
.stat-label { display: block; margin-bottom: 3px; color: #b9cbd1; font-size: .75rem; font-weight: 800; letter-spacing: .1em; }
.stat strong { font-size: 1.75rem; line-height: 1; font-variant-numeric: tabular-nums; }
.seconds { margin-left: 3px; color: #b9cbd1; font-size: 1rem; }
.board { display: grid; grid-template-columns: repeat(3, 1fr); gap: 12px; width: 100%; aspect-ratio: 1; padding: 12px; border: 1px solid #527080; border-radius: 20px; background: #182e3c; }
.hole { position: relative; display: grid; place-items: center; min-width: 0; padding: 0; overflow: hidden; border: 0; border-radius: 50%; background: #315344; box-shadow: inset 0 8px 0 #172b3a, inset 0 -7px 0 #243f35; cursor: pointer; transition: background .15s, transform .12s; }
.hole:hover { background: #3b654e; }
.hole:active { transform: scale(.94); }
.hole:focus-visible, .start-button:focus-visible { outline: 3px solid var(--gold); outline-offset: 3px; }
.mole { display: grid; place-items: center; width: 62%; height: 62%; border: 5px solid #a85c43; border-radius: 45% 45% 40% 40%; background: #dc9061; color: #542f2b; font-size: 0; opacity: 0; transform: translateY(75%); transition: transform .12s ease-out, opacity .12s; }
.mole::before { content: ""; width: 24%; height: 24%; border-radius: 50%; background: #542f2b; box-shadow: 18px 0 #542f2b; }
.hole.active .mole { opacity: 1; transform: translateY(8%); }
.message { min-height: 24px; margin: 18px 0 12px; color: #d3e0db; }
.start-button { width: 100%; min-height: 52px; border: 0; border-radius: 14px; background: var(--green); color: #193326; font: inherit; font-weight: 850; cursor: pointer; transition: background .15s, transform .12s, box-shadow .15s; }
.start-button:hover { background: #a7e58e; box-shadow: 0 6px 20px #8ecf7640; }
.start-button:active { transform: translateY(2px) scale(.99); }
.hint { margin: 14px 0 0; color: #b9cbd1; font-size: .875rem; }
@media (max-width: 400px) { .game-card { padding-top: 26px; } .board { gap: 9px; padding: 9px; } }

const holes = [...document.querySelectorAll('.hole')];
const scoreDisplay = document.querySelector('#score');
const timeDisplay = document.querySelector('#time');
const message = document.querySelector('#message');
const startButton = document.querySelector('#start');

let score = 0;
let secondsLeft = 30;
let activeHole = -1;
let gameTimer;
let moleTimer;

function showMole() {
  holes.forEach(hole => hole.classList.remove('active'));
  let next = Math.floor(Math.random() * holes.length);
  if (holes.length > 1 && next === activeHole) next = (next + 1 + Math.floor(Math.random() * (holes.length - 1))) % holes.length;
  activeHole = next;
  holes[activeHole].classList.add('active');
}

function endGame() {
  clearInterval(gameTimer);
  clearInterval(moleTimer);
  holes.forEach(hole => hole.classList.remove('active'));
  activeHole = -1;
  timeDisplay.textContent = '0';
  message.textContent = `Game over! Final score: ${score}.`;
  startButton.disabled = false;
  startButton.textContent = 'Play again';
}

function startGame() {
  clearInterval(gameTimer);
  clearInterval(moleTimer);
  score = 0;
  secondsLeft = 30;
  activeHole = -1;
  scoreDisplay.textContent = '0';
  timeDisplay.textContent = '30';
  message.textContent = 'Catch the mole!';
  startButton.disabled = true;
  startButton.textContent = 'Playing…';
  showMole();
  moleTimer = setInterval(showMole, 1000);
  gameTimer = setInterval(() => {
    secondsLeft -= 1;
    timeDisplay.textContent = String(secondsLeft);
    if (secondsLeft <= 0) endGame();
  }, 1000);
}

holes.forEach((hole, index) => {
  hole.addEventListener('click', () => {
    if (secondsLeft <= 0 || startButton.disabled === false || index !== activeHole) return;
    score += 1;
    scoreDisplay.textContent = String(score);
    message.textContent = 'Nice hit!';
    showMole();
  });
});
startButton.addEventListener('click', startGame);
